static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}static void Reject(Action a,string label){bool rejected=false;try{a();}catch(InvalidDataException){rejected=true;}Check(rejected,label);}
static Project Fixture(){var p=new Project();p.Earthing="TT";p.Source.LineVoltage=400;p.Source.ShortCircuitKA=6;var b=new Board{Id="Q",Voltage=400};var c=new Circuit{Id="C",Phases=PhaseMode.Trifasico,PhaseLabel="ABC",Voltage=400,PowerKw=8*Math.Sqrt(3),PowerFactor=1,CableMm2=10};c.Cable.AmpacityA=32;b.Circuits.Add(c);p.Boards.Add(b);BreakerSelection.Apply(p,c,new BreakerRating{Manufacturer="QA",Reference="BR25",VoltageV=400,FrequencyHz=60,Poles=PoleLayout.ThreePole,RatedA=25,CapacityKA=10,I2A=36.25,Metric=BreakingMetric.Icu,Source="Fonte QA",DataVersion="2026.10",Standard="QA",Sheet="QA"},PoleLayout.ThreePole,BreakingMetric.Icu);c.Protection.EarthResistanceOhm=100;return p;}
static ResidualRating Rating(Project p,bool relay){var c=p.Boards[0].Circuits[0];return new ResidualRating{Kind=relay?ResidualKind.ResidualRelay:ResidualKind.RCCB,Manufacturer="QA sintético",Reference=relay?"ELR-QA":"RCCB-QA",Waveform=ResidualWaveform.A,VoltageV=400,FrequencyHz=60,Poles=PoleLayout.ThreePole,RatedA=40,DeltaMilliA=30,ConditionalKA=10,RequiredPrimaryConfiguration=ResidualSelection.PrimaryConfiguration(c),SensorReference=relay?"CT-QA":"",ActuatorReference=relay?"TRIP24-QA":"",AccessoryReference=relay?"AUX-QA":"",AssemblyDocument="Conjunto sintético QA; sem certificação",ControlVoltageV=relay?24:0,ControlSupply=relay?ControlSupply.DC:ControlSupply.NotApplicable,Source="Fonte sintética; \"A\" Ω",DataVersion="2026.10",Standard="Classe declarada QA",Conditions="Ensaio AC400V/60Hz; sem seletividade presumida"};}
static ResidualBinding Binding(ResidualRating r){return new ResidualBinding{Engine=ResidualSelection.EngineId,Rating=r,RequiredWaveform=ResidualWaveform.A,RequiredPoles=PoleLayout.ThreePole,MaximumDeltaMilliA=30,RequirementSource="Regra de ensaio sintético; não normativa",ControlVoltageV=r.Kind==ResidualKind.ResidualRelay?24:0,ControlSupply=r.Kind==ResidualKind.ResidualRelay?ControlSupply.DC:ControlSupply.NotApplicable};}
static ResidualEvaluation Eval(Project p,ResidualBinding b){return ResidualSelection.Evaluate(p,Engineering.Analyze(p),p.Boards[0].Circuits[0],b);}
[STAThread]public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"residual-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{var p=Fixture();var c=p.Boards[0].Circuits[0];var r=Rating(p,false);var b=Binding(r);Check(Eval(p,b).Status=="Atende comparações nominais","RCCB exact conditions nominal current conditional short and TT contact");r.DeltaMilliA=31;Check(Eval(p,b).Status=="Não atende","sensitivity above declared rule rejected");r.DeltaMilliA=30;r.RatedA=19;Check(Eval(p,b).Status=="Não atende","insufficient through current rejected");r.RatedA=24;Check(Eval(p,b).Status=="Não atende","primary rating above RCCB In rejected");r.RatedA=40;r.Waveform=ResidualWaveform.B;Check(Eval(p,b).Status=="Não atende","required residual type must match");r.Waveform=ResidualWaveform.A;r.Poles=PoleLayout.FourPole;Check(Eval(p,b).Status=="Não atende","required pole configuration must match");r.Poles=PoleLayout.ThreePole;r.VoltageV=415;Check(Eval(p,b).Status=="Não atende","voltage not extrapolated");r.VoltageV=400;r.FrequencyHz=50;Check(Eval(p,b).Status=="Não atende","frequency must match");r.FrequencyHz=60;b.RequiredWaveform=ResidualWaveform.Unknown;Check(Eval(p,b).Status=="Dados incompletos","unknown application waveform requirement stays pending");b.RequiredWaveform=ResidualWaveform.A;b.MaximumDeltaMilliA=0;b.RequirementSource="";Check(Eval(p,b).Status=="Dados incompletos","sensitivity limit not guessed from customary values");b.MaximumDeltaMilliA=30;b.RequirementSource="Regra QA";r.ConditionalKA=0;r.RequiredPrimaryConfiguration="";Check(Eval(p,b).Status=="Dados incompletos","no short association evidence remains pending");r.ConditionalKA=5;r.RequiredPrimaryConfiguration=ResidualSelection.PrimaryConfiguration(c);Check(Eval(p,b).Status=="Não atende","insufficient conditional short withstand rejected");r.ConditionalKA=10;c.Protection.MagneticTripA=125;Check(Eval(p,b).Status=="Dados incompletos","primary setting change invalidates declared association");c.Protection.MagneticTripA=0;c.Protection.EarthResistanceOhm=2000;Check(Eval(p,b).Status=="Não atende","TT contact limit exceeded");c.Protection.EarthResistanceOhm=0;Check(Eval(p,b).Status=="Dados incompletos","unknown earth resistance stays pending");c.Protection.EarthResistanceOhm=100;p.Earthing="TN-C";Check(Eval(p,b).Status=="Não atende","RCD not accepted in TN-C PEN section");p.Earthing="TN-C-S";Check(Eval(p,b).Status=="Dados incompletos","unidentified PEN separation not inferred");p.Earthing="IT";Check(Eval(p,b).Status=="Dados incompletos","IT fault model not assumed from RCD presence");p.Earthing="TN-S";Check(Eval(p,b).Status=="Atende comparações nominais","known TN-S nominal additional selection without assuming TT Ra rule");p.Earthing="TT";p.Source.ShortCircuitKA=0;Check(Eval(p,b).Status=="Dados incompletos","unknown fault current remains pending");p.Source.ShortCircuitKA=6;
c.DriveMotor=new DriveMotorData{DriveReference="Drive QA",MotorReference="Motor QA",InputRatedA=40,OutputRatedA=25,OutputVoltageV=400,MotorRatedA=20,MotorVoltageV=400,MotorShaftKw=5,Source="QA"};Check(Eval(p,b).Status=="Dados incompletos","drive residual/DC behavior requires specific manufacturer review");c.DriveMotor=null;var noAccessoryProof=Rating(p,false);noAccessoryProof.AccessoryReference="AUX-UNKNOWN";noAccessoryProof.ConditionalKA=0;noAccessoryProof.RequiredPrimaryConfiguration="";noAccessoryProof.AssemblyDocument="";Check(Eval(p,Binding(noAccessoryProof)).Status=="Dados incompletos"&&Eval(p,Binding(noAccessoryProof)).Detail.Contains("Acessório associado"),"accessory without association document is not assumed compatible");
var relay=Rating(p,true);var rb=Binding(relay);Check(Eval(p,rb).Status=="Atende comparações nominais","documented relay sensor actuator accessory and control assembly");relay.SensorReference="";Check(Eval(p,rb).Status=="Dados incompletos","missing sensor stays pending");relay.SensorReference="CT-QA";relay.ActuatorReference="";Check(Eval(p,rb).Status=="Dados incompletos","relay alone does not disconnect without actuator");relay.ActuatorReference="TRIP24-QA";rb.ControlVoltageV=230;Check(Eval(p,rb).Status=="Não atende","wrong auxiliary voltage rejected");rb.ControlVoltageV=24;rb.ControlSupply=ControlSupply.AC;Check(Eval(p,rb).Status=="Não atende","wrong auxiliary AC/DC supply rejected");rb.ControlVoltageV=0;rb.ControlSupply=ControlSupply.NotApplicable;Check(Eval(p,rb).Status=="Dados incompletos","unknown auxiliary circuit remains pending");rb.ControlVoltageV=24;rb.ControlSupply=ControlSupply.DC;
string beforeContext=Coordination.Configuration(c);ResidualSelection.Apply(p,c,rb);Check(c.ResidualSelection!=rb&&c.ResidualSelection.Rating!=relay,"binding owns independent assembly reference");Check(c.Protection.RcdMilliA==0&&c.BreakerA==25&&c.Protection.BreakingCapacityKA==10,"additional RCD does not overwrite primary device values");Check(Coordination.Configuration(c)!=beforeContext&&ResidualSelection.PrimaryConfiguration(c)==r.RequiredPrimaryConfiguration,"physical residual assembly changes pair context without circular primary binding");relay.SensorReference="Edited afterwards";Check(c.ResidualSelection.Rating.SensorReference=="CT-QA","later library edit cannot change selected hardware");Check(Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Diferencial / relé / acessórios"&&x.Status=="Atende comparações nominais"),"selected differential assembly appears in complete study");var old=c.ResidualSelection;var wrong=Binding(Rating(p,false));wrong.Rating.VoltageV=230;Reject(delegate{ResidualSelection.Apply(p,c,wrong);},"bad selection cannot apply");Check(Object.ReferenceEquals(old,c.ResidualSelection),"rejected selection leaves assembly intact");
string csv=Path.Combine(dir,"table.csv");var rows=new[]{Rating(p,false),Rating(p,true)};ResidualSelection.Export(rows,csv);var imported=ResidualSelection.Import(csv);Check(imported.Count==2&&imported[0].Source==rows[0].Source&&imported[1].AccessoryReference=="AUX-QA","generic CSV roundtrips enums Unicode association and accessory");ResidualSelection.Export(new ResidualRating[0],Path.Combine(dir,"empty.csv"));Check(ResidualSelection.Import(Path.Combine(dir,"empty.csv")).Count==0,"empty schema supported");var model=ResidualSelection.Template(p,c,ResidualKind.RCCB);Check(Eval(p,Binding(model)).Status!="Atende comparações nominais","placeholder example cannot approve");ResidualSelection.Export(rows,csv);var before=File.ReadAllBytes(csv);var backup=File.ReadAllBytes(csv+".bak");var invalid=Rating(p,false);invalid.Source="";Reject(delegate{ResidualSelection.Export(new[]{invalid},csv);},"missing source rejected");Check(File.ReadAllBytes(csv).SequenceEqual(before)&&File.ReadAllBytes(csv+".bak").SequenceEqual(backup),"invalid export preserves library and backup");Reject(delegate{ResidualSelection.Export(new[]{rows[0],rows[0].Copy()},csv);},"duplicate assembly condition rejected");invalid=Rating(p,false);invalid.SensorReference="external";Reject(invalid.Validate,"RCCB cannot hide external relay sensor conditions");invalid=Rating(p,false);invalid.ControlVoltageV=24;invalid.ControlSupply=ControlSupply.DC;Reject(invalid.Validate,"RCCB ignores no auxiliary relay fields");invalid=Rating(p,false);invalid.Waveform=ResidualWaveform.Unknown;Reject(invalid.Validate,"unknown device waveform cannot be treated as AC by default");invalid=Rating(p,true);invalid.ControlVoltageV=0;Reject(invalid.Validate,"partial control metadata rejected");invalid=Rating(p,false);invalid.RequiredPrimaryConfiguration="bad";Reject(invalid.Validate,"malformed association configuration rejected");var invalidRule=Binding(Rating(p,false));invalidRule.RequirementSource="";Reject(invalidRule.Validate,"limit needs its rule reference");foreach(double value in new[]{0,-1,double.NaN,double.PositiveInfinity}){invalid=Rating(p,false);invalid.DeltaMilliA=value;Reject(invalid.Validate,"invalid sensitivity rejected");}
string malformed=Path.Combine(dir,"bad.csv");File.WriteAllText(malformed,ResidualSelection.Header+"\nRCCB;too;few\n");Reject(delegate{ResidualSelection.Import(malformed);},"wrong column count rejected");string text=File.ReadAllText(csv);File.WriteAllText(malformed,text.Replace("\"RCCB\"","\"futureDevice\""));Reject(delegate{ResidualSelection.Import(malformed);},"unknown CSV enum rejected");string large=Path.Combine(dir,"large.csv");using(var stream=File.Create(large))stream.SetLength(32L*1024*1024+1);Reject(delegate{ResidualSelection.Import(large);},"oversized import rejected");var huge=new List<ResidualRating>();string big=new string('x',2000);for(int i=0;i<6000;i++){var value=Rating(p,false);value.Reference="BIG-"+i;value.Source=value.DataVersion=value.Conditions=big;huge.Add(value);}Reject(delegate{ResidualSelection.Export(huge,csv);},"oversized export rejected");Check(File.ReadAllBytes(csv).SequenceEqual(before)&&File.ReadAllBytes(csv+".bak").SequenceEqual(backup)&&Directory.GetFiles(dir,"*.tmp").Length==0,"overflow preserves files and removes temporary data");
string project=Path.Combine(dir,"project.circuito");p.Save(project);string saved=File.ReadAllText(project);Check(saved.Contains("residual-assemblies-v1")&&saved.Contains("\"FileVersion\":4"),"new capability guards residual assembly");var loaded=Project.Load(project);Check(loaded.Boards[0].Circuits[0].ResidualSelection.Rating.ActuatorReference=="TRIP24-QA","actuator and hardware survive reopen");Check(EngineeringReport.Memory(p,Engineering.Analyze(p))==EngineeringReport.Memory(loaded,Engineering.Analyze(loaded)),"complete residual report reproduces after reopen");var copy=ProjectEditing.DuplicateCircuit(p,p.Boards[0],c);Check(copy.ResidualSelection!=c.ResidualSelection&&copy.ResidualSelection.Rating!=c.ResidualSelection.Rating,"duplicate owns independent residual assembly");p.Boards[0].Circuits.Remove(copy);File.WriteAllText(project,saved.Replace(ResidualSelection.EngineId,"future-residual-engine"));Reject(delegate{Project.Load(project);},"unknown residual evaluator revision rejected");File.WriteAllText(project,saved);string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrWhiteSpace(previous)){var assembly=Assembly.LoadFile(Path.GetFullPath(previous));bool rejected=false;try{assembly.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{project});}catch(TargetInvocationException ex){rejected=ex.InnerException is InvalidDataException;}Check(rejected,"actual previous reader rejects new residual capability");}
string artifacts=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-diferenciais");Directory.CreateDirectory(artifacts);p.Save(Path.Combine(artifacts,"origem.circuito"));ResidualSelection.Export(rows,Path.Combine(artifacts,"tabela.csv"));File.WriteAllText(Path.Combine(artifacts,"resultado.txt"),ResidualSelection.Evaluate(p,Engineering.Analyze(p),c,c.ResidualSelection).Detail,new UTF8Encoding(true));EngineeringReport.Materials(p,Path.Combine(artifacts,"materiais.csv"));Check(File.ReadAllText(Path.Combine(artifacts,"materiais.csv")).Contains("AUX-QA")&&File.ReadAllText(Path.Combine(artifacts,"materiais.csv")).Contains("Conjunto diferencial selecionado"),"materials preserve relay sensor actuator accessory assembly");using(var form=new ResidualSelectionForm(p,c,csv)){form.CreateControl();Check(!form.Changed,"opening residual selector does not change project");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();form.Refresh();form.Update();using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(artifacts,"diferenciais.png"));}form.Hide();}}
Console.WriteLine("PASS: "+n+" residual-assembly assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(dir,true);}}
